WITH cleaned AS (SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag, COALESCE(merchant, 'OTHER') AS merchant_clean FROM transactions WHERE txn_time > TIMESTAMP '2023-07-24 07:00:00' AND merchant IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT txn_type, SIZE(COLLECT_SET(merchant)) AS num_merchants, MIN(is_flagged_flag) AS min_is_flagged_flag FROM islands GROUP BY txn_type
